import { Schema } from 'effect'
import { RunId, WorkspaceId } from './scalars'
import { SandboxRequest, SandboxResult } from './sandbox'

export const RuntimeExecutionKind = Schema.Literals(['exec', 'tool_invocation', 'workflow'])
export type RuntimeExecutionKind = typeof RuntimeExecutionKind.Type

export const RuntimeExecutionRequest = Schema.Struct({
  workspace_id: WorkspaceId,
  kind: RuntimeExecutionKind,
  run_id: Schema.optional(RunId),
  payload: Schema.Unknown,
  low_level: Schema.optional(SandboxRequest),
})
export type RuntimeExecutionRequest = typeof RuntimeExecutionRequest.Type

export const RuntimeExecutionResult = Schema.Struct({
  ok: Schema.Boolean,
  run_id: Schema.optional(RunId),
  output: Schema.optional(Schema.Unknown),
  error: Schema.optional(Schema.String),
  low_level: Schema.optional(SandboxResult),
})
export type RuntimeExecutionResult = typeof RuntimeExecutionResult.Type
