import { Context, Effect, Schema } from 'effect'

const NonNegativeInteger = Schema.Number.check(Schema.isInt(), Schema.isGreaterThanOrEqualTo(0))
const PositiveInteger = Schema.Number.check(Schema.isInt(), Schema.isGreaterThanOrEqualTo(1))

export const RateLimitScope = Schema.Literals(['workspace', 'user', 'agent', 'ip', 'public'])
export type RateLimitScope = typeof RateLimitScope.Type

export const RateLimitPolicy = Schema.Struct({
  id: Schema.String,
  scope: RateLimitScope,
  windowMs: PositiveInteger,
  max: PositiveInteger,
  costUnit: Schema.optional(Schema.String),
})
export type RateLimitPolicy = typeof RateLimitPolicy.Type

export const RateLimitBucketSnapshot = Schema.Struct({
  windowStartMs: NonNegativeInteger,
  count: NonNegativeInteger,
})
export type RateLimitBucketSnapshot = typeof RateLimitBucketSnapshot.Type

export const RateLimitInfo = Schema.Struct({
  policy_id: Schema.String,
  scope: RateLimitScope,
  limit: PositiveInteger,
  window_ms: PositiveInteger,
  remaining: NonNegativeInteger,
  reset_at_ms: PositiveInteger,
})
export type RateLimitInfo = typeof RateLimitInfo.Type

export const RateLimitDecision = Schema.Struct({
  allowed: Schema.Boolean,
  retryAfterSec: NonNegativeInteger,
  remaining: NonNegativeInteger,
  resetAtMs: PositiveInteger,
  bucket: RateLimitBucketSnapshot,
  info: RateLimitInfo,
})
export type RateLimitDecision = typeof RateLimitDecision.Type

export const ApiRateLimitFailure = Schema.Struct({
  success: Schema.Literal(false),
  error: Schema.String,
  retry_after_sec: PositiveInteger,
  rate_limit: RateLimitInfo,
})
export type ApiRateLimitFailure = typeof ApiRateLimitFailure.Type

export interface FixedWindowRateLimitStore {
  readonly get: (key: string) => RateLimitBucketSnapshot | undefined
  readonly set: (key: string, bucket: RateLimitBucketSnapshot) => void
}

export interface FixedWindowRateLimitInput {
  readonly policy: RateLimitPolicy
  readonly bucket?: RateLimitBucketSnapshot | undefined
  readonly cost?: number | undefined
  readonly nowMs?: number | undefined
}

export interface ApplyFixedWindowRateLimitInput extends FixedWindowRateLimitInput {
  readonly key: string
  readonly store: FixedWindowRateLimitStore
}

const normalizeCost = (cost: number | undefined): number => {
  if (cost === undefined) return 1
  if (!Number.isFinite(cost)) return 1
  return Math.max(1, Math.trunc(cost))
}

const retryAfterSeconds = (resetAtMs: number, nowMs: number): number =>
  Math.max(1, Math.ceil((resetAtMs - nowMs) / 1000))

const decisionInfo = (
  policy: RateLimitPolicy,
  remaining: number,
  resetAtMs: number
): RateLimitInfo => ({
  policy_id: policy.id,
  scope: policy.scope,
  limit: policy.max,
  window_ms: policy.windowMs,
  remaining,
  reset_at_ms: resetAtMs,
})

export const evaluateFixedWindowRateLimit = (
  input: FixedWindowRateLimitInput
): RateLimitDecision => {
  const nowMs = Math.max(0, Math.trunc(input.nowMs ?? Date.now()))
  const cost = normalizeCost(input.cost)
  const current = input.bucket
  const expired = !current || nowMs - current.windowStartMs >= input.policy.windowMs
  const bucket = expired ? { windowStartMs: nowMs, count: 0 } : current
  const projected = bucket.count + cost
  const resetAtMs = bucket.windowStartMs + input.policy.windowMs

  if (projected > input.policy.max) {
    const remaining = Math.max(0, input.policy.max - bucket.count)
    return {
      allowed: false,
      retryAfterSec: retryAfterSeconds(resetAtMs, nowMs),
      remaining,
      resetAtMs,
      bucket,
      info: decisionInfo(input.policy, remaining, resetAtMs),
    }
  }

  const nextBucket = { ...bucket, count: projected }
  const remaining = Math.max(0, input.policy.max - projected)
  return {
    allowed: true,
    retryAfterSec: 0,
    remaining,
    resetAtMs,
    bucket: nextBucket,
    info: decisionInfo(input.policy, remaining, resetAtMs),
  }
}

export const applyFixedWindowRateLimit = (
  input: ApplyFixedWindowRateLimitInput
): RateLimitDecision => {
  const decision = evaluateFixedWindowRateLimit({
    policy: input.policy,
    bucket: input.store.get(input.key),
    cost: input.cost,
    nowMs: input.nowMs,
  })
  if (decision.allowed) input.store.set(input.key, decision.bucket)
  return decision
}

export interface RateLimiter {
  readonly check: (input: {
    readonly key: string
    readonly policy: RateLimitPolicy
    readonly cost?: number | undefined
  }) => Effect.Effect<RateLimitDecision>
}

export const RateLimiter = Context.Service<RateLimiter>('@hrbr/core/RateLimiter')

export const makeInMemoryRateLimiter = (
  store = new Map<string, RateLimitBucketSnapshot>(),
  now: () => number = Date.now
): RateLimiter => ({
  check: (input) =>
    Effect.sync(() =>
      applyFixedWindowRateLimit({
        ...input,
        store,
        nowMs: now(),
      })
    ),
})
